package com.bqsqwad.heartbreakhealer.feature.entertainment

/** Four original ten-part serials, each with a resolved final chapter. */
internal object StoryLibraryBatch5 {
    val stories = listOf(
        StorySeries("the_clockmakers_daughter", "The Clockmaker's Daughter", "A young apprentice uncovers the story behind a town clock that has kept perfect time for a century.", listOf(
            StoryPart(1, "The Stopped Minute", listOf("When Ada began helping at her aunt's repair shop, she expected broken radios and loose watch straps. Instead, a customer brought in a pocket watch that stopped at exactly 4:12 every afternoon.", "The watch belonged to a clockmaker who had built the town hall clock. A note inside its case said: 'Find the minute that was left out.'")),
            StoryPart(2, "The Town Hall Face", listOf("Ada visited the town hall and noticed that the clock face had eleven marks between four and five, not twelve. The caretaker said it had always been that way.", "An old photograph showed a complete clock face. Ada wondered when the missing mark had disappeared and why nobody had repaired it.")),
            StoryPart(3, "The Apprentice's Book", listOf("The local museum held the clockmaker's apprentice journal. Its pages described a disagreement about the clock's design and a missing brass marker.", "The journal's last entry named a young apprentice, Sola, who had left town before the clock was unveiled. Ada searched the town directory for her family.")),
            StoryPart(4, "A Family Keepsake", listOf("Sola's grandson welcomed Ada and showed her a small wooden case. Inside was a brass marker engraved with the number twelve and the clockmaker's initials.", "He said his grandmother had kept it because she believed the clockmaker had intended to return for it. She never learned why he did not.")),
            StoryPart(5, "The Workshop Letter", listOf("A letter in the case explained that the marker had been removed during a rushed installation. The clockmaker planned to fit it later, but a disagreement over the credit for the design had ended their partnership.", "The letter also included a signed drawing proving that Sola had designed the clock's unusual chime mechanism.")),
            StoryPart(6, "The Missing Credit", listOf("Ada compared the drawing with the museum records. The public display credited only the clockmaker, though the workshop ledger listed both names.", "The museum director agreed to review the evidence and contact Sola's family before making any correction. Ada realised the mystery was about recognition as much as a missing piece.")),
            StoryPart(7, "A Careful Restoration", listOf("The town hired a qualified horologist to inspect the clock before any repair. Ada was invited to observe, but the expert handled the mechanism and explained each step.", "The missing marker was not essential to the clock's operation. It could be restored safely after the inspection and the town's approval.")),
            StoryPart(8, "Two Names on the Plan", listOf("The museum confirmed the drawing and ledger were authentic. The director prepared a new display describing both creators and the different contributions each had made.", "Sola's grandson asked that the display include apprentices and craftspeople too, not only the people whose names appeared on the main contract.")),
            StoryPart(9, "The Twelve Mark", listOf("At a public ceremony, the horologist fitted the restored marker. The clock face was cleaned, and the museum unveiled the corrected history beside it.", "Ada watched the minute hand move past the repaired mark. The clock had not been broken by a missing number; the town's story had simply been incomplete.")),
            StoryPart(10, "Time Kept Fairly", listOf("Sola's family donated copies of her drawings, and the museum began a project to identify other overlooked contributors to local landmarks. Ada returned to the repair shop with a new respect for careful records.", "At 4:12, the pocket watch began ticking again after the horologist completed its service. Ada smiled at the sound. The mystery had ended with the clock restored, the right names recognised, and a reminder that good work should be credited honestly."))
        )),
        StorySeries("the_library_of_lost_sounds", "The Library of Lost Sounds", "A student archivist collects everyday sounds and discovers the story of a community radio station.", listOf(
            StoryPart(1, "A Box of Cassettes", listOf("Noah volunteered to digitise old recordings at the library. Most tapes held interviews, school concerts, and weather reports, but one box was labelled only 'Sounds we should keep'.", "The first cassette contained the sound of a market opening, followed by a familiar voice saying, 'If you can hear this, the station is still here.'")),
            StoryPart(2, "The Station's Call Sign", listOf("The library catalogue linked the tape to a community radio station that had closed fifteen years earlier. Noah's neighbour remembered the station as a place where residents shared local news and music.", "A faded sticker on the cassette showed the call sign and a time: Saturday, 10 a.m. Noah decided to visit the old studio building.")),
            StoryPart(3, "The Empty Studio", listOf("The building now housed a youth centre. Its manager allowed Noah to inspect a cupboard of donated equipment, where he found a handwritten broadcast schedule.", "The schedule listed a weekly segment called 'Voices of the Block'. Each episode recorded a local sound and the memory connected to it.")),
            StoryPart(4, "The Sound Collector", listOf("A retired presenter, Mrs James, explained that the programme had been created to preserve stories that might otherwise disappear. She had kept copies of some scripts but not the recordings.", "She remembered one final episode that was never broadcast because the station lost its funding. The script named a group of residents who had helped save the old market.")),
            StoryPart(5, "The Unbroadcast Script", listOf("Noah found the script in the library's local history collection. It included interviews with traders, cleaners, and delivery workers, each describing how the market supported the neighbourhood.", "The final page listed a recording location: the clock tower steps, at sunrise. Mrs James said the voices might still be on a reel stored with the station's former engineer.")),
            StoryPart(6, "The Engineer's Reel", listOf("The engineer's daughter found the reel in a labelled case. She agreed to let the library digitise it, provided the family received a copy and the recordings were not edited to change anyone's meaning.", "The audio included the missing episode and a short message from the station team explaining why they had stopped broadcasting.")),
            StoryPart(7, "Why the Station Closed", listOf("The team had not closed because the community stopped listening. Their transmitter lease ended, and the station could not afford the new equipment required by the regulator.", "The recording also revealed that the station had donated its remaining equipment to the youth centre. The building's new purpose had grown from the old station's final act.")),
            StoryPart(8, "A New Listening Room", listOf("Noah proposed a listening room at the library where people could hear the restored recordings and add their own memories. The librarian approved a small pilot with clear consent forms and privacy choices.", "Mrs James helped label each recording with its date and contributors. The engineer's family reviewed the audio before it was made available.")),
            StoryPart(9, "The First New Broadcast", listOf("The youth centre hosted a live listening event. Residents heard the market sounds, then recorded new memories about places that had changed over time.", "Noah made sure every participant chose whether their recording could be shared publicly, kept privately, or not retained. The project became a lesson in preserving stories respectfully.")),
            StoryPart(10, "A Sound That Stays", listOf("The library opened its listening room with the original unbroadcast episode as its first feature. The station's former team attended, and the youth centre agreed to host a monthly community audio workshop.", "Noah added a final recording of the market opening that morning. The old station did not return to the air, but its purpose had found a new home: voices were being heard, memories were safely preserved, and the neighbourhood could tell its own story."))
        )),
        StorySeries("the_map_of_kindness", "The Map of Kindness", "A student cartographer turns scattered acts of help into a practical guide for neighbours.", listOf(
            StoryPart(1, "A Map with Blank Spaces", listOf("During geography club, Reni found an old neighbourhood map with blank circles drawn across it. A note said: 'Mark every place where someone helped.'", "Her teacher explained that the map had been part of a community project, but the students who started it had graduated before finishing.")),
            StoryPart(2, "The First Circle", listOf("The first circle marked a water point near the market. An older trader remembered volunteers repairing its tap after a storm, but nobody had recorded who organised the work.", "Reni asked the market association for old meeting notes. They found a list of volunteers and a receipt for the repair.")),
            StoryPart(3, "The Blue Bicycle", listOf("Another circle marked a bicycle repair shop. The owner remembered lending tools to students who cycled to school and could not afford small repairs.", "He had never considered it a community service. Reni asked permission to include the shop on the map as a place offering occasional help.")),
            StoryPart(4, "A Better Legend", listOf("The original map used only dots, so nobody knew what each place offered. Reni created symbols for free learning support, repair help, accessible services, and community spaces.", "Her teacher reminded her to verify every listing and ask before publishing names or contact details. Reni added a date beside each confirmed entry.")),
            StoryPart(5, "The Closed Centre", listOf("One circle marked a centre that had shut down. A rumour said its volunteers had misused donations, but the records showed the building had been closed for structural repairs.", "Reni contacted the former coordinator, who provided the inspection notice and a list of organisations that had continued the centre's activities elsewhere.")),
            StoryPart(6, "Following the Volunteers", listOf("The volunteers had moved their tutoring sessions to a church hall and their food collection to a registered community group. The map could point people to the new locations instead of repeating outdated information.", "Reni visited each organisation with a teacher and confirmed its opening times, accessibility, and permission to be listed.")),
            StoryPart(7, "The Missing Route", listOf("A student using a wheelchair explained that some places on the map were difficult to reach because the route included steps. Reni realised that a helpful map needed access information, not just addresses.", "The geography club added route notes and asked each location to confirm whether its entrance was step-free or had assistance available.")),
            StoryPart(8, "A Map for Everyone", listOf("The team made a large-print version and a simple digital version that could be updated. They included a note telling users to confirm details before travelling because services can change.", "The market association offered to display the map, while the library agreed to keep the latest copy.")),
            StoryPart(9, "Checking the Details", listOf("Before launch, Reni and her teacher contacted every listed place again. Two opening times had changed, and one service had paused for the school holidays.", "They corrected the information and added a review date to each listing. The map was now a living guide rather than a collection of guesses.")),
            StoryPart(10, "The Neighbourhood in One Page", listOf("At the launch, residents used the map to find study groups, repair help, and community spaces. Several businesses asked how they could offer useful services without sharing private information.", "Reni placed the original map in the school archive and kept the updated guide at the library. The blank circles had become a verified network of practical help. The project ended with a clear lesson: kindness becomes easier to find when information is accurate, consent is respected, and someone takes responsibility for keeping the map current."))
        )),
        StorySeries("the_rooftop_observatory", "The Rooftop Observatory", "A science club restores a neglected telescope and discovers the value of patient observation.", listOf(
            StoryPart(1, "A Covered Telescope", listOf("The science club found an old telescope under a weather cover on the school rooftop. It belonged to a former teacher, but no one knew whether it still worked.", "Club president Fara wanted to use it for the upcoming astronomy night. Their teacher said they first needed an equipment inspection and permission to access the roof.")),
            StoryPart(2, "The Inventory Card", listOf("The school inventory listed the telescope's model and a maintenance log. The last entry said the lens cap was missing and the mount needed professional attention.", "A note named the supplier, a small optics shop that still operated across town. Fara wrote to ask whether the model could be serviced.")),
            StoryPart(3, "The Optician's Advice", listOf("The shop technician inspected the telescope and explained that its optics were sound, but the mount needed adjustment. He advised against forcing any stiff parts.", "The school approved a repair and asked the technician to demonstrate safe setup to the club. Fara added the instructions to the equipment folder.")),
            StoryPart(4, "The Old Star Chart", listOf("Inside the storage cabinet, the students found a star chart drawn by the former teacher. Several constellations were labelled with local names used in lessons years ago.", "The librarian found a school newsletter describing the teacher's astronomy nights. Former students remembered how the sessions had inspired them to study science.")),
            StoryPart(5, "A Message in the Margin", listOf("The chart's margin contained a note: 'Do not promise a planet. Promise a clear view and a patient eye.' Fara wondered whether the teacher had been warning students about cloudy skies.", "The science teacher explained that astronomy required patience. The club decided to plan an event with indoor activities as well as rooftop observation, so the evening could still be useful if clouds arrived.")),
            StoryPart(6, "The Weather Plan", listOf("The students checked a forecast and prepared a backup programme about moon phases, star charts, and light pollution. They also arranged adult supervision and a clear rooftop access limit.", "A local astronomy group agreed to bring a second telescope and help visitors use it safely.")),
            StoryPart(7, "The First Clear Night", listOf("The first rehearsal took place under a clear sky. The technician checked the mount, and the students practised explaining how to focus without touching the glass.", "Fara found the moon through the eyepiece and stepped aside so the next student could take a turn. The club agreed that everyone should have equal time at the telescope.")),
            StoryPart(8, "Clouds at the Event", listOf("On the night of the event, clouds covered much of the sky. A few visitors looked disappointed, but the students began the indoor programme and showed how astronomers use charts and repeated observations.", "Later, a gap opened in the clouds. The group saw the moon for several minutes, then returned indoors before the weather changed again.")),
            StoryPart(9, "The Teacher's Return", listOf("A former student contacted the retired teacher, who joined the club by video call. She was delighted that the telescope had been repaired and that the students had kept her chart.", "She explained the local constellation names and encouraged the club to record their own observations rather than copy answers from a book.")),
            StoryPart(10, "A Sky Worth Sharing", listOf("The school established a monthly astronomy evening with safe access rules, adult supervision, equipment checks, and an indoor alternative. The old teacher donated her annotated star chart to the science archive.", "Fara wrote a new note beside the telescope: 'Look carefully. Share the view. Leave the equipment ready for the next person.' The telescope had been restored, the club had learned to plan responsibly, and the observatory had become a place where curiosity could be shared."))
        ))
    )
}
